update cosmetics_product
goods_name = #{goodsName}, category = #{category}, brand = #{brand}, price = #{price}, stock = #{stock}, condition_level = #{conditionLevel}, image = #{image}, description = #{description}, notice = #{notice}, status = #{status}, update_by = #{updateBy}, update_time = sysdate(), version = version + 1
